import{_ as t,c as a,o as n,ae as i}from"./chunks/framework.Bi6zybwU.js";const b=JSON.parse('{"title":"Table Rendering Settings","description":"Table Rendering Settings","frontmatter":{"title":"Table Rendering Settings","description":"Table Rendering Settings"},"headers":[],"relativePath":"guide/table-settings/table-rendering-settings.md","filePath":"guide/table-settings/table-rendering-settings.md"}'),s={name:"guide/table-settings/table-rendering-settings.md"};function l(o,e,r,h,g,d){return n(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="table-rendering-settings" tabindex="-1">Table Rendering Settings <a class="header-anchor" href="#table-rendering-settings" aria-label="Permalink to &quot;Table Rendering Settings&quot;">​</a></h1><p>Ninja Tables offers <strong>Table</strong> <strong>Rendering Settings</strong> which is used for the table render method. You can select between two- Ajax table &amp; Advanced table (Legacy). Table Rendering Settings <strong>Advanced Table (Legacy)</strong> is a Pro Feature! Go to the <strong>Table</strong> <strong>Configuration</strong> tab and you&#39;ll see Rendering Settings on the left menubar. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-table-rendering-settings-1024x467.webp" alt="New Ui table rendering settings"></p><h2 id="ajax-table" tabindex="-1"><strong>Ajax Table</strong> <a class="header-anchor" href="#ajax-table" aria-label="Permalink to &quot;**Ajax Table**&quot;">​</a></h2><p>You should use the <strong>Ajax</strong> <strong>Rendering</strong> <strong>Method</strong> when your table has a large amount of data. Here, data will load as a chunk. Also, you can change the minimum chunk size by adding some code to the theme&#39;s functions.php file. For example, we have set the minimum chunk size at 100.</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">add_filter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ninja_table_per_chunk&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($limit) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>In this mode, you can&#39;t use the cell merge/split feature or shortcodes in cells.</p><h2 id="legacy-table" tabindex="-1"><strong>Legacy</strong> Table <a class="header-anchor" href="#legacy-table" aria-label="Permalink to &quot;**Legacy** Table&quot;">​</a></h2><p>In the <strong>Legacy Rendering Mode</strong>, the table loads in full HTML format and is totally readable by Google. But Google readable doesn&#39;t mean that the data will show precisely in Google search rather, it depends on how you have set the table data in SEO. Advanced Table (Legacy) is a Pro Feature! To use the table cell merge/split feature and Shortcodes in cells, you must set Rendering Setting to Legacy.</p><h2 id="caching-configuration" tabindex="-1"><strong>Caching</strong> Configuration <a class="header-anchor" href="#caching-configuration" aria-label="Permalink to &quot;**Caching** Configuration&quot;">​</a></h2><p>To optimize and load faster, we cache the table contents. <strong>Disable caching is not recommended</strong> unless you know what you are doing. The frontend Loader is disabled by default. The loader you turned on will be visible when you click the Preview button while the table is loading.</p><h2 id="enable-full-html-cache" tabindex="-1"><strong>Enable Full HTML Cache</strong> <a class="header-anchor" href="#enable-full-html-cache" aria-label="Permalink to &quot;**Enable Full HTML Cache**&quot;">​</a></h2><p>If you enable this, Ninja Tables will cache the full HTML of the table and render that without interacting with the database. You can set the time for how many <strong>minutes</strong> it will cache each iteration. Don&#39;t forget to click on the <strong>Update</strong> <strong>Configuration</strong> button when you are done!</p>`,12)])])}const u=t(s,[["render",l]]);export{b as __pageData,u as default};
